for a0 in 0..128:
    for a1 in 0..128:
        for a2 in 0..512:
            in0 = load a[a0, a2]
            in1 = load b[a2, a1]
            f32 v0 = multiply(in0, in1)
            acc0 <- add(acc0, v0) over a2
        o[a0, a1] = acc0

for a0 in 0..2:
    for a1 in 0..128:
        for a2 in 0..128:
            for a3 in 0..256 window(parent=a3 in 0..512, partition=true):
                in0 = load b[256 * a0 + a3, a2]
                in1 = load a[a1, 256 * a0 + a3]
                f32 v0 = multiply(in0, in1)
                acc0 <- add(acc0, v0) over a3
            o__partial[a0, a1, a2] = acc0

for a0 in 0..128:
    for a1 in 0..128:
        for a2 in 0..2 window(parent=a2 in 0..2, partition=true):
            in0 = load o__partial[a2, a0, a1]
            acc0 <- add(acc0, in0) over a2
        o[a0, a1] = acc0
